import{_ as n,h as o,i as e,c as s,v as t,p as l,x as r,m as d,e as p,S as c}from"./chunks/framework.Dvtg8yj2.js";const g=JSON.parse('{"title":"静态批 vs 动态批","description":"","frontmatter":{"title":"静态批 vs 动态批","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/static-vs-dynamic-batch.md","filePath":"llm/static-vs-dynamic-batch.md","lastUpdated":1788454257000}'),B={name:"llm/static-vs-dynamic-batch.md"};function E(h,a,m,A,_,T){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="静态批-vs-动态批" tabindex="-1">静态批 vs 动态批 <a class="header-anchor" href="#静态批-vs-动态批" aria-label="Permalink to &quot;静态批 vs 动态批&quot;">​</a></h1><div class="epigraph"><p>请求级批处理把一批请求绑到全部结束；迭代级批处理允许成员在逐步生成中途改变——二者的空隙与延迟画像完全不同。</p><footer>—— 对照 Yu et al., Orca, OSDI 2022 中对 request-level 与 iteration-level 批处理的区分</footer></div><p>批处理是把多条请求的张量叠在一起，摊掉启动开销、吃满矩阵乘。自回归之前，这个「一起」的时间范围通常是一次完整前向：进一条、出一条，批的寿命等于一次模型调用。生成式 Transformer 让一次请求变成许多次调用，于是「静态批」和「动态批」不再只是 padding 技巧，而是两种对<strong>批之寿命</strong>的定义。静态：组成批次后，成员集合冻结，直到所有人写完。动态：成员集合可在逐步生成中更新——<a href="/llm/continuous-batching">连续批处理</a> 是其在线形态。本篇对照二者的空隙、延迟、实现假设，以及何时静态反而更好。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>推理框架若从分类、embedding、encoder-decoder 一次性解码的经验出发，会自然写成：凑满 \\(B\\) 条或等到超时，pad 到批内最大长度，一次（或固定步数）跑完，整批返回。这对「每条请求恰好一次前向」是对的。对 GPT 类解码，一次前向只产一个 token，总步数等于输出长度。把「凑批」的语义沿用成「这 \\(B\\) 条必须同步走完所有步」，就会出现两类浪费：步数已结束的行在陪跑；尚未凑进批的请求在等待最长同伴。</p><p>动态批要回答的问题对称：若允许每步改变成员，引擎还能不能走同一套矩阵乘？注意力序列长度各异，线性层的 token 却可以拼在一起。静态批用 padding 回避这个问题；动态批必须正视变长，否则只是把静态批的 \\(B\\) 改成「有时小一点」——那叫可变批大小，还不是成员可变的动态批。</p><h3 id="三种容易混的「动态」" tabindex="-1">三种容易混的「动态」 <a class="header-anchor" href="#三种容易混的「动态」" aria-label="Permalink to &quot;三种容易混的「动态」&quot;">​</a></h3><p>「动态」在文献和产品里至少三义。其一，<strong>可变批大小</strong>：这一次前向 \\(B=8\\)，下一次 \\(B=4\\)，但每次前向内部成员固定且通常跑完请求。其二，<strong>动态 padding / 打包</strong>：训练或离线推理按 token 数凑包，减少 pad。其三，<strong>迭代级成员变更</strong>：Orca 意义上的动态，批的身份在 decode 步之间改写。本篇的静态 vs 动态，主要指第一、第三义在生成服务里的对立；打包是正交的长度对齐手段。</p><p><span class="marginnote">产品文档写「支持动态 batching」时，先问一句：已结束的序列能不能在下一步从前向里消失、新序列能不能在下一步出现。能，才是生成服务要的动态批；只能在两次「整请求」之间改 \\(B\\)，对自回归气泡没有帮助。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>静态批的生命周期：队列中取出最多 \\(B\\) 条 → 分配连续 KV → 循环 decode 直到批内全部 EOS 或触达 <code>max_new_tokens</code> → 整批释放。实现简单：批维稳定，CUDA Graph 好捕获，注意力可以用规整的 <code>[B,S,H,D]</code>。代价是 \\(S\\) 取批内最大，短序列的 pad 在注意力里被掩掉但仍占计算与显存；更致命的是短序列在步数维上的陪跑。</p><h3 id="静态批如何用-padding-换规整核" tabindex="-1">静态批如何用 padding 换规整核 <a class="header-anchor" href="#静态批如何用-padding-换规整核" aria-label="Permalink to &quot;静态批如何用 padding 换规整核&quot;">​</a></h3><p>设批内提示长度 \\(s_i\\)、生成预算 \\(t_i\\)。静态实现常把张量做到 \\(\\max s_i\\) 与 \\(\\max t_i\\)。注意力 FLOPs 按最大值计，有效工作按均值计。长度越不齐，效率越差。离线、可排序的负载可以把相近长度的请求分桶，让静态批重新变好——这是「静态批 + 长度分桶」，不是动态批。在线对话无法等待未来的短请求来填桶，分桶策略失效。</p><p>动态批的生命周期：每步根据当前 KV 与公平策略选出集合 \\(\\mathcal{B}_t\\) → 只对 \\(\\mathcal{B}_t\\) 做一次迭代 → 更新结束标记 → \\(t\\leftarrow t+1\\)。张量形状每步可变。线性层把各请求的当步 token 拼成一维再 GEMM，即 Orca 的选择性批处理里「非注意力可批」的那一半；注意力按请求或按分页块来，避免为短序列垫到长序列的 \\(S\\)。</p>',14)),(e(),l(c,null,{default:r(()=>[p(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20STAT%5B%22%E9%9D%99%E6%80%81%E6%89%B9%22%5D%0A%20%20%20%20A1%5B%22%E5%87%91%E6%BB%A1%20B%20%E6%9D%A1%22%5D%20--%3E%20A2%5B%22%E6%88%90%E5%91%98%E5%86%BB%E7%BB%93%22%5D%0A%20%20%20%20A2%20--%3E%20A3%5B%22%E5%90%8C%E6%AD%A5%20decode%20%E5%88%B0%E5%85%A8%E7%BB%93%E6%9D%9F%22%5D%0A%20%20%20%20A3%20--%3E%20A4%5B%22%E6%95%B4%E6%89%B9%E8%BF%94%E5%9B%9E%22%5D%0A%20%20end%0A%20%20subgraph%20DYN%5B%22%E5%8A%A8%E6%80%81%E6%89%B9%22%5D%0A%20%20%20%20B1%5B%22%E5%BD%93%E5%89%8D%E5%8F%AF%E8%BF%90%E8%A1%8C%E9%9B%86%E5%90%88%22%5D%20--%3E%20B2%5B%22%E4%B8%80%E6%AC%A1%E8%BF%AD%E4%BB%A3%22%5D%0A%20%20%20%20B2%20--%3E%20B3%5B%22%E7%BB%93%E6%9D%9F%E8%80%85%E7%A6%BB%E5%BC%80%20%2F%20%E5%88%B0%E8%BE%BE%E8%80%85%E8%BF%9B%E5%85%A5%22%5D%0A%20%20%20%20B3%20--%3E%20B1%0A%20%20end%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="等待凑批-vs-立即开跑" tabindex="-1">等待凑批 vs 立即开跑 <a class="header-anchor" href="#等待凑批-vs-立即开跑" aria-label="Permalink to &quot;等待凑批 vs 立即开跑&quot;">​</a></h3><p>静态批还有一个时间轴上的旋钮：为了抬 \\(B\\)，可以等待更多到达。等待提高算术强度，损害 TTFT。动态批通常来一条、下一迭代就能进引擎（受 KV 槽限制），用时间上的连续填充代替空间上的凑批等待。高 QPS 时两者都容易把 GPU 填满，差别主要在空隙；低 QPS 时静态批的等待策略特别伤交互延迟，动态批可以在 \\(B=1\\) 时立刻开跑，有人来了再胀上去。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>从利用率看，静态批的有效算力份额大致是 \\(\\mathbb{E}[\\mathrm{mean}(T)/\\max(T)]\\) 再乘以 padding 效率。输出长度服从长尾时，\\(\\max(T)\\) 被尾部拉高，均值跟不上，空隙是结构性的。动态批的有效份额接近「当时能放入 KV 池的并发」，空隙来自瞬时到达不足或槽位耗尽，而不是来自批内同步。</p><p>从延迟看，静态批的 E2E 含凑批等待 + 批内最慢同伴的生成时间；动态批的 E2E 含排队等槽 + 自身 \\(T\\) 步，每步的墙钟随当时 \\(\\lvert\\mathcal{B}\\rvert\\) 变。所以动态批改善的是<strong>别人的长度不再进入你的关键路径</strong>，不是让你自己的每步更快。批变大时每步更慢，这是吞吐–延迟权衡，静态动态都有；动态只是把权衡从「整批」改成「当前迭代」。</p><p><span class="marginnote">把动态批理解成「每步更快」会在容量规划里犯错。它提高的是系统吞吐和短请求的排队，单步延迟往往因平均并发上升而略增。SLA 要分开写 TTFT 与 TPOT，不能只用一条 E2E。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>静态批没有过时。离线评测、温度采样对比、同一提示的 beam 族、embedding 与分类、长度几乎相同的批处理作业，规整核 + 一张 CUDA Graph 往往更快、更好 profiling。动态批的调度税、形状变化、图捕获失效，在这些负载上是纯开销。</p><p>在线生成里，静态批只适合能接受「整批返回」语义的 API（一些内部管道、一次性摘要）。面向聊天与流式 token 的网关，动态批几乎是默认。两者可以分层：入口按优先级分成若干队列，队列内部动态批；离线低优队列用静态大包打满空闲。不要在同一引擎实例里用一套超参同时追求离线峰值和在线 P99。</p><p><span class="marginnote">对照实验若把静态批的 \\(B\\) 设得很小以「降低延迟」，再拿动态批的大并发比吞吐，是在比两个不同工作点。应在同一延迟约束下画吞吐曲线，或在同一吞吐下画延迟分位数——Orca 相对 FasterTransformer 的读法就是这样。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>静态批冻结成员直到全结束，实现规整，空隙等于批内长度不齐与同步步数。</li><li>动态批在迭代边界改写成员，短请求不再陪跑长请求，在线生成是主场。</li><li>「可变 \\(B\\)」不是「成员中途可进出」；生成服务要的是后者。</li><li>动态批改善排队与气泡，不保证每步更快；TTFT / TPOT 要分列。</li><li>齐整离线负载上静态批加长度分桶仍然更干净。</li><li>二者可以按队列分层，不要用同一工作点比较峰值。</li><li>出处：Yu et al., <em>Orca</em>, OSDI 2022（request-level vs iteration-level）。连续批是动态批的在线名称，机制专文见 iteration-level 调度。</li></ul>',12))])}const b=n(B,[["render",E]]);export{g as __pageData,b as default};
